      "seccion": "MD-L000031-L000036"
    },
    {
      "cita_literal_breve": "Una respuesta truncada, una negativa recibida, una falta de evidencia y un fallo de transporte tienen causas distintas; no generan automáticamente el valor U.",
      "documento": "CYB-01",
